public static class CombinationNormalizer
{
    public static List<List<int>> Normalize(List<List<int>> combos)
    {
        var sorted = combos.Select(c => { var copy = new List<int>(c); copy.Sort(); return copy; }).ToList();
        sorted.Sort((a, b) =>
        {
            for (var i = 0; i < Math.Min(a.Count, b.Count); i++) if (a[i] != b[i]) return a[i] - b[i];
            return a.Count - b.Count;
        });
        return sorted;
    }
}

